"""One Wings compile/smoke: source mesh, all settings, real bridge and GPU depth/styles."""
from pathlib import Path
import argparse,json,os,runpy,shutil,subprocess
HERE=Path(__file__).resolve().parent;ROOT=HERE.parents[1]
def main():
 p=argparse.ArgumentParser();p.add_argument('--out',required=True);a=p.parse_args();out=ROOT/a.out
 if(out/'report.json').exists():raise SystemExit('Refusing to overwrite evidence')
 out.mkdir(parents=True,exist_ok=True);body=runpy.run_path(str(HERE/'test-reset-vl.py'))['body'];shared=(HERE/'engine/src/config.rs').read_text(encoding='utf8')
 config='use std::collections::BTreeMap;use serde_json::{Value,Map,Number,json};\n#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub enum JsonFormat{File,Interop}\n#[derive(Clone,Copy,Debug)]enum ModuleKind{Breadcrumbs,Wings}impl ModuleKind{fn key(self)->&\'static str{match self{Self::Breadcrumbs=>"liquidbounce.module.breadcrumbs",Self::Wings=>"liquidbounce.module.wings"}}}\n'
 for anchor in['pub struct CommonSettings','pub struct ConfigError','impl ConfigError',"struct Tree<'a>","impl Tree<'_>",'fn scalar_string(',"fn nodes<'a>(",'fn float_json(',"fn value_of<'a>(",'fn parse_float(','fn parse_int(','fn decimal_int(','fn parse_bool(','\nfn leaf(']:
  if anchor=='pub struct ConfigError':config+='#[derive(Debug)]\n'
  config+=body(shared,anchor)+'\n'
 config+='type Nodes<\'a>=BTreeMap<String,&\'a Value>;\n#[derive(Debug)]pub enum SettingChange{Breadcrumbs(breadcrumbs::BreadcrumbsSetting),Wings(settings::WingsSetting)}\n'+body(shared,'pub struct SettingsPatch')+'\n'
 config+=f'#[path="{(HERE/"engine/src/config/breadcrumbs.rs").as_posix()}"]mod breadcrumbs;pub use breadcrumbs::*;\n#[path="{(HERE/"engine/src/config/wings.rs").as_posix()}"]mod settings;pub use settings::*;\n'
 config+='''#[test]fn complete_wings_tree_and_inactive_shader_styles_roundtrip(){let mut s=crate::wings::Wings::default();s.height=-0.7;s.back_offset=0.4;s.equipment_offset=0.8;s.show_damage=false;s.first_person=true;s.view_on_friend=false;s.distance=123;s.length=1.7;s.width=0.12;s.fade_start=0.8;s.count=11;s.angles=[2,86];s.color=0x33778899;s.render.shader=true;s.render.style=8;for(i,style)in s.render.styles.iter_mut().enumerate(){style.values.insert("Opacity".into(),i as f32/10.);if [2,5].contains(&i){style.accent=0x11223344;}}let common=CommonSettings{enabled:true,hidden:false,key_bind:json!({})};for format in[JsonFormat::File,JsonFormat::Interop]{let tree=serialize_wings(&s,&common,format,&str::to_owned).unwrap();let mut patch=SettingsPatch{module:ModuleKind::Wings,changes:vec![],issues:vec![]};settings::parse_wings(&mut patch,&nodes(&tree,"Wings","Wings").unwrap());assert!(patch.issues.is_empty(),"{:?}",patch.issues);let mut restored=crate::wings::Wings::default();for c in patch.changes{if let SettingChange::Wings(v)=c{v.apply(&mut restored)}}assert_eq!(restored,s);assert!(!tree.to_string().contains("liquidbounce.module.breadcrumbs"));let values=tree["value"].as_array().unwrap();assert!(values.iter().any(|v|v["name"]=="Position"));assert!(!values.iter().any(|v|v["name"]=="Render"));let m=values.iter().find(|v|v["name"]=="Mode").unwrap();assert_eq!(m["active"],"Lines");let lines=m["choices"]["Lines"]["value"].as_array().unwrap();assert!(lines.iter().any(|v|v["name"]=="Render"));let angles=lines.iter().find(|v|v["name"]=="Angles").unwrap();assert_eq!(angles["value"],json!({"from":2,"to":86}));}}\n'''
 (out/'config.rs').write_text(config,encoding='utf8')
 renderer=runpy.run_path(str(HERE/'wings-render.py'))['source']().replace('include_str!("breadcrumbs',f'include_str!("{HERE.as_posix()}/breadcrumbs').replace('include_str!("wings.wgsl")',f'include_str!("{(HERE/"wings.wgsl").as_posix()}")');(out/'render.rs').write_text(renderer,encoding='utf8')
 lib='#![allow(dead_code)]\nextern crate self as liquidbounce_behaviors;extern crate self as horizon_client;\n'
 for name in['breadcrumbs','wings']:lib+=f'#[path="{(ROOT/f"native/liquidbounce-behaviors/src/{name}.rs").as_posix()}"]pub mod {name};\n'
 lib+='mod config;mod render;\n'
 lib+='''pub mod mod_api{pub trait Host{}pub struct NullHost;impl Host for NullHost{}pub struct ClientWingsEvent<'a>{pub input:&'a str,pub geometry:&'a mut String}}
pub mod runtime{use std::{cell::RefCell,rc::Rc};pub struct Module;impl Module{pub fn enabled(&self)->bool{false}}pub struct Registry;impl Registry{pub fn module(&self,_:u32)->Option<Module>{None}}pub struct Modules{pub wings:crate::wings::Wings,pub query_ids:std::collections::BTreeMap<&'static str,u32>}impl Modules{pub fn query_running(&self,_:&Registry,_:&str)->bool{true}}pub struct State{pub behaviors:RefCell<Modules>,pub registry:Registry,pub friends:std::collections::BTreeSet<String>}pub struct LiquidBounceHooks{state:Rc<State>}impl Default for LiquidBounceHooks{fn default()->Self{Self{state:Rc::new(State{behaviors:RefCell::new(Modules{wings:Default::default(),query_ids:std::collections::BTreeMap::from_iter([("FreeLook",0)])}),registry:Registry,friends:std::collections::BTreeSet::from_iter(["friend".to_owned()])})}}}impl LiquidBounceHooks{pub fn state(&self)->Rc<State>{self.state.clone()}}}
'''
 lib+=f'#[path="{(HERE/"engine/src/wings_runtime.rs").as_posix()}"]mod wings_runtime;\n';lib+=(HERE/'wings-native-fixture.rs').read_text(encoding='utf8').replace('NATIVE_PATH',(HERE/'wings-game.rs').as_posix());lib+=(HERE/'wings-smoke.rs').read_text(encoding='utf8');(out/'lib.rs').write_text(lib,encoding='utf8')
 manifest=(ROOT/'build/breadcrumbs-smoke-03/Cargo.toml').read_text(encoding='utf8').replace('name="breadcrumbs-smoke"','name="wings-smoke"');(out/'Cargo.toml').write_text(manifest,encoding='utf8')
 patched={};base=ROOT/'build/staging/horizon';error=None;metadata=None
 def once(t,o,n):assert t.count(o)==1,(o,t.count(o));return t.replace(o,n)
 def edit(path,op):patched[path]=op(patched.get(path,(base/path).read_text(encoding='utf8')if(base/path).exists()else''))
 try:
  metadata=runpy.run_path(str(HERE/'wings-patch.py'))['apply'](edit,once)
  for path,text in patched.items():target=out/'patched'/path;target.parent.mkdir(parents=True,exist_ok=True);target.write_text(text,encoding='utf8')
 except Exception as e:error=repr(e)
 locale=out/'localization';locale.mkdir(exist_ok=True);updater=runpy.run_path(str(HERE/'update-wings-locales.py'));counts={}
 for language in['zh_cn','zh_tw']:
  target=locale/f'display_{language}.json';shutil.copyfile(ROOT/f'native/liquidbounce-interop/resources/localization/display_{language}.json',target);updater['update'](language,target);d=json.loads(target.read_text(encoding='utf8'));counts[language]=sum(k.startswith('liquidbounce.module.wings')for k in d['descriptions']);assert not any(k.startswith('liquidbounce.module.wings')for k in d)
 loc=(ROOT/'native/liquidbounce-interop/src/localization.rs').read_text(encoding='utf8').split('#[cfg(test)]')[0]
 for name in ['display_zh_cn','display_zh_tw','en_us','zh_cn','zh_tw','module_keys']:
  target=locale/f'{name}.json'if name.startswith('display_')else ROOT/f'native/liquidbounce-interop/resources/localization/{name}.json';loc=loc.replace(f'../resources/localization/{name}.json',target.as_posix())
 (out/'localization.rs').write_text(loc,encoding='utf8');lib+='mod localization;\n#[test]fn actual_display_dictionary_resolves_both_chinese_locales(){assert_eq!(localization::display_label("zh_cn","FadeStartRatio"),"渐隐起点");assert_eq!(localization::display_label("zh_tw","ShowInFirstPerson"),"第一人稱顯示");for l in["zh_cn","zh_tw"]{let key="liquidbounce.module.wings.mode.lines.render.shader.style.smooth.fill.description";let value=localization::describe(l,key);assert!(!value.contains("0.15"));assert!(value.contains("1"));assert!(!localization::describe(l,"liquidbounce.module.wings.mode.lines.length.description").contains("liquidbounce"));}}\n';(out/'lib.rs').write_text(lib,encoding='utf8')
 env=os.environ.copy();env['CARGO_TARGET_DIR']=str(HERE/'packet-tests/target');r=subprocess.run(['cargo','+stable','test','--offline','--manifest-path',str(out/'Cargo.toml')],cwd=ROOT,env=env,capture_output=True,text=True,encoding='utf8',errors='replace');(out/'test.log').write_text(r.stdout+r.stderr,encoding='utf8')
 report={'passed':r.returncode==0 and error is None,'compileExit':r.returncode,'patchError':error,'metadata':metadata,'patchedFiles':len(patched),'localeKeys':counts,'scope':'Production Wings mesh/all settings/runtime/native Game bridge/independent GPU renderer. Real WGPU Plain plus all nine source GLSL styles; scene depth cuts both plain and shader silhouettes, including vertical orientation. Native Game, registry and Host declaration providers. Patch composes in memory; copied dictionaries. LAN body state uses actual guest movement/swing/vehicle inputs and native player-model tickHeadTurn. Actual official native/engine aggregate and game visual parity remain root-owned.'}
 (out/'report.json').write_text(json.dumps(report,indent=2)+'\n',encoding='utf8');print(json.dumps(report));raise SystemExit(0 if report['passed']else 1)
if __name__=='__main__':main()
